import{_ as t,o as i,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const f=JSON.parse('{"title":"CDS Hammer (Day 1) - Buffer Encoding","description":"","frontmatter":{"title":"CDS Hammer (Day 1) - Buffer Encoding","date":"2014-10-29T00:00:00.000Z","updated":"2014-10-30T00:00:00.000Z","tags":["Ceph","Buffer Encoding","Performance Optimization","Distributed Storage","CephFS"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/CDS_Hammer_Day_1_-_Buffer_Encoding.md","filePath":"posts/2014/CDS_Hammer_Day_1_-_Buffer_Encoding.md","lastUpdated":1780459816000}'),n={name:"posts/2014/CDS_Hammer_Day_1_-_Buffer_Encoding.md"};function e(s,l,a,p,g,_){return i(),r("div",null,[...l[0]||(l[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： Ceph 分布式存储缓冲编码优化讨论</p><p><strong>会议时间</strong>： 2023年某月某日</p><p><strong>参会人员</strong>： Sam、Matt、Alan 等</p><p><strong>会议内容</strong>：</p><p><strong>一、会议背景</strong></p><p>Ceph 分布式存储集群负载分析中显示，缓冲编码和编解码过程是性能瓶颈之一。</p><p><strong>二、讨论议题</strong></p><ol><li><p><strong>缓冲编码性能问题</strong>：</p><ul><li>缓冲列表追加路径深度导致性能损耗。</li><li>编码和编解码过程中存在函数调用开销。</li><li>编码和编解码路径存在重复计算和冗余操作。</li></ul></li><li><p><strong>优化方案</strong>：</p><ul><li><strong>微优化</strong>： <ul><li>内联代码，减少函数调用开销。</li><li>优化代码路径，减少重复计算和冗余操作。</li><li>减少缓冲追加和编码操作的次数。</li></ul></li><li><strong>重构消息结构</strong>： <ul><li>将消息结构重构为固定大小，减少内存拷贝。</li><li>使用内存映射技术，将内存表示与网络表示统一。</li><li>使用 flat buffers 等库进行序列化。</li></ul></li></ul></li><li><p><strong>兼容性问题</strong>：</p><ul><li>重构消息结构可能影响向后兼容性。</li></ul></li></ol><p><strong>三、决定事项</strong></p><ol><li><p><strong>优先进行微优化</strong>：</p><ul><li>对现有结构进行微优化，观察效果。</li><li>了解缓冲列表拷贝操作调用频率，优化相关代码。</li></ul></li><li><p><strong>研究 flat buffers</strong>：</p><ul><li>研究 flat buffers 的应用，考虑其在 Ceph 中的适用性。</li></ul></li><li><p><strong>继续研究消息结构重构</strong>：</p><ul><li>研究消息结构重构的可行性，评估其对向后兼容性的影响。</li></ul></li></ol><p><strong>四、后续行动计划</strong></p><ol><li>Matt 和 Sam 继续研究缓冲编码优化方案，并在邮件列表上分享进展。</li><li>Sam 和其他成员研究 flat buffers 的应用，评估其在 Ceph 中的适用性。</li><li>Alan 研究消息结构重构的可行性，评估其对向后兼容性的影响。</li></ol><p><strong>五、其他事项</strong></p><ol><li>讨论了 Ceph 分布式存储的内存对齐问题。</li><li>Matt 提到了正在进行的优化方案，包括优化缓冲指针和共享策略。</li></ol><p><strong>六、会议总结</strong></p><p>本次会议讨论了 Ceph 分布式存储缓冲编码优化方案，明确了后续行动计划。会议强调了微优化和消息结构重构的重要性，并要求团队成员继续研究相关技术。</p>',17)])])}const d=t(n,[["render",e]]);export{f as __pageData,d as default};
